const match = $json.url.match(/^(https?:\/\/)([^\/]+)/i);
if (!match || !$json.site) throw new Error('Invalid portal crawl');
const origin = match[1] + match[2];
return [{ json: {
  targetUrl: origin,
  targetHostname: match[2].toLowerCase().replace(/:(80|443)$/, ''),
  siteName: $json.site,
  excludePaths: [],
  recheckIntervalHours: 168,
  autoDeleteStale: true,
  robotsUrl: origin + '/robots.txt',
  sitemapUrl: origin + '/sitemap.xml'
} }];

const raw = $input.first().json.data || '';
const lines = raw.split('\n');

const groups = [];
let currentGroup = null;

for (let line of lines) {
  line = line.replace(/#.*$/, '').trim();
  if (!line) continue;

  const colonIdx = line.indexOf(':');
  if (colonIdx === -1) continue;

  const directive = line.substring(0, colonIdx).trim().toLowerCase();
  const value = line.substring(colonIdx + 1).trim();

  if (directive === 'user-agent') {
    const agent = value.toLowerCase();
    if (!currentGroup || currentGroup.hasRules) {
      currentGroup = { agents: [], rules: [], hasRules: false };
      groups.push(currentGroup);
    }
    currentGroup.agents.push(agent);
  } else if (currentGroup && (directive === 'disallow' || directive === 'allow')) {
    currentGroup.hasRules = true;
    if (!value) {
      if (directive === 'disallow') {
        currentGroup.rules = [];
      }
      continue;
    }

    const hasEndAnchor = value.endsWith('$');
    const cleanVal = hasEndAnchor ? value.slice(0, -1) : value;

    let regexStr = cleanVal
      .replace(/[.+?^${}()|[\]\\]/g, '\\$&')
      .replace(/\*/g, '.*');

    regexStr = '^' + regexStr + (hasEndAnchor ? '$' : '.*');

    currentGroup.rules.push({
      type: directive,
      path: value,
      pattern: regexStr,
      length: value.length
    });
  }
}

// 匹配优先级：优先专属 agent (crawl4ai)，若无则降级匹配通配符 *
let selectedGroup = groups.find(g => g.agents.includes('crawl4ai'));
if (!selectedGroup) {
  selectedGroup = groups.find(g => g.agents.includes('*'));
}

const effectiveRules = selectedGroup ? selectedGroup.rules : [];

return [{
  json: {
    rawRobots: raw,
    rules: effectiveRules,
    disallowRegexes: effectiveRules.filter(r => r.type === 'disallow').map(r => r.pattern)
  }
}];

// 解析 SitemapIndex，提取所有子 Sitemap URL，并附加主页作为保底种子
const config = $('⚙️ Workflow Config (修改网站入口)').first().json;
const data = $input.first().json;
const subSitemaps = [];
const seedUrls = [config.targetUrl];

if (data.sitemapindex && data.sitemapindex.sitemap) {
  const sitemaps = Array.isArray(data.sitemapindex.sitemap) 
    ? data.sitemapindex.sitemap 
    : [data.sitemapindex.sitemap];

  for (const item of sitemaps) {
    if (item.loc) subSitemaps.push(item.loc);
  }
} else if (data.urlset && data.urlset.url) {
  const urls = Array.isArray(data.urlset.url) ? data.urlset.url : [data.urlset.url];
  for (const item of urls) {
    if (item.loc) seedUrls.push(item.loc);
  }
}

// 如果没有子 Sitemap，则直接返回原始 sitemapUrl
if (subSitemaps.length === 0) {
  subSitemaps.push(config.sitemapUrl);
}

return subSitemaps.map(url => ({ json: { sitemapUrl: url, seedUrls } }));

// =========================================================================
// 全局统一 URL 规范化函数 (Single Canonicalization Engine)
// =========================================================================
function normalizeUrl(raw, baseUrl) {
  if (!raw) return '';
  let href = raw.trim();
  if (href.startsWith('javascript:') || href.startsWith('mailto:') || href.startsWith('tel:')) return '';

  let full = '';
  try {
    if (href.startsWith('http://') || href.startsWith('https://')) {
      full = href;
    } else if (href.startsWith('//')) {
      full = 'https:' + href;
    } else if (href.startsWith('/')) {
      full = baseUrl.replace(/\/+$/, '') + href;
    } else {
      full = baseUrl.replace(/\/+$/, '') + '/' + href;
    }

    const match = full.match(/^(https?:\/\/)([^\/]+)(\/[^?#]*)?(\?[^#]*)?(#.*)?$/i);
    if (!match) return '';

    let scheme = match[1].toLowerCase();
    let host = match[2].toLowerCase().replace(/:(80|443)$/, '');
    let path = (match[3] || '/').replace(/\/+/g, '/');
    let search = match[4] || '';

    // 解析去除 ./ 与 ../
    const segments = [];
    for (const seg of path.split('/')) {
      if (seg === '' || seg === '.') continue;
      if (seg === '..') {
        if (segments.length > 0) segments.pop();
      } else {
        segments.push(seg);
      }
    }
    let cleanPath = '/' + segments.join('/');
    if (cleanPath.length > 1 && cleanPath.endsWith('/')) {
      cleanPath = cleanPath.slice(0, -1);
    }

    // 剔除常见营销追踪参数
    if (search) {
      const parts = search.substring(1).split('&');
      const filtered = [];
      for (const p of parts) {
        const k = p.split('=')[0];
        if (!/^utm_|^fbclid$|^gclid$|^_ga$|^ref$/i.test(k)) {
          filtered.push(p);
        }
      }
      search = filtered.length > 0 ? ('?' + filtered.join('&')) : '';
    }

    return scheme + host + cleanPath + search;
  } catch (e) {
    return '';
  }
}

// 严格同源/子域名判断（彻底杜绝 evilasterspring.com.sg 穿透漏洞）
function isAllowedHost(host, target) {
  if (!host || !target) return false;
  host = host.toLowerCase().replace(/:(80|443)$/, '');
  target = target.toLowerCase().replace(/:(80|443)$/, '');
  return host === target || host.endsWith('.' + target);
}

const config = $('⚙️ Workflow Config (修改网站入口)').first().json;
const targetHostname = config.targetHostname;
const baseUrl = config.targetUrl;

const allUrls = [{ url: baseUrl.replace(/\/+$/, ''), lastmod: null, sourceOrigin: 'seed_homepage' }];

let sitemapCount = 0;
for (const item of $input.all()) {
  const data = item.json;
  if (data.urlset && data.urlset.url) {
    const urlList = Array.isArray(data.urlset.url) ? data.urlset.url : [data.urlset.url];
    for (const u of urlList) {
      if (u.loc) {
        const norm = normalizeUrl(u.loc, baseUrl);
        if (norm) {
          const uHost = norm.match(/^https?:\/\/([^\/]+)/i)?.[1];
          if (isAllowedHost(uHost, targetHostname)) {
            sitemapCount++;
            allUrls.push({
              url: norm,
              lastmod: u.lastmod ? u.lastmod.trim() : null,
              sourceOrigin: 'sitemap'
            });
          }
        }
      }
    }
  }
}

// 提取首页一阶内链 (Homepage Level-1 Link Discovery)
let homepageHtml = '';
let probeCount = 0;
try {
  const probeData = $('Fetch Homepage (First-Level Discovery)').first()?.json;
  homepageHtml = probeData?.data || probeData?.body || '';
} catch (e) {
  homepageHtml = '';
}

if (homepageHtml) {
  const regex = /href\s*=\s*["']([^"'#\s>]+)["']/gi;
  let match;
  while ((match = regex.exec(homepageHtml)) !== null) {
    const rawHref = match[1].trim();
    const norm = normalizeUrl(rawHref, baseUrl);
    if (!norm) continue;

    // 静态文件与系统保留字过滤
    if (/\.(png|jpg|jpeg|gif|svg|webp|pdf|zip|mp4|css|js|woff|woff2|ico|xml|rss|atom|json|txt)$/i.test(norm)) continue;
    if (/blog-feed|sitemap|robots\.txt/i.test(norm)) continue;

    const uHost = norm.match(/^https?:\/\/([^\/]+)/i)?.[1];
    if (isAllowedHost(uHost, targetHostname)) {
      probeCount++;
      allUrls.push({ url: norm, lastmod: null, sourceOrigin: 'homepage_probe' });
    }
  }
}

// 智能聚合去重
const urlMap = new Map();
const duplicateMap = new Map();

for (const item of allUrls) {
  if (!item.url) continue;
  const canonical = item.url;
  const existing = urlMap.get(canonical);

  if (!existing) {
    urlMap.set(canonical, {
      url: canonical,
      lastmod: item.lastmod,
      sourceOrigin: item.sourceOrigin
    });
  } else {
    let dupRecord = duplicateMap.get(canonical);
    if (!dupRecord) {
      dupRecord = {
        canonicalUrl: canonical,
        occurrences: 1,
        sources: [existing.sourceOrigin]
      };
      duplicateMap.set(canonical, dupRecord);
    }
    dupRecord.occurrences++;
    if (!dupRecord.sources.includes(item.sourceOrigin)) {
      dupRecord.sources.push(item.sourceOrigin);
    }
    if (item.lastmod && (!existing.lastmod || item.lastmod > existing.lastmod)) {
      existing.lastmod = item.lastmod;
    }
  }
}

const duplicateLinks = Array.from(duplicateMap.values()).map(d => ({
  canonicalUrl: d.canonicalUrl,
  occurrences: d.occurrences,
  sources: d.sources,
  reason: `Discovered ${d.occurrences} times across [${d.sources.join(', ')}]; merged into canonical identity`
}));

const discovery = { duplicateLinks, sitemapCount, probeCount,
  rawDiscoveredCount: allUrls.length, uniquePagesCount: urlMap.size };
return Array.from(urlMap.values()).map(item => ({ json: { ...item, discovery } }));

function isAllowedHost(host, target) {
  if (!host || !target) return false;
  host = host.toLowerCase().replace(/:(80|443)$/, '');
  target = target.toLowerCase().replace(/:(80|443)$/, '');
  return host === target || host.endsWith('.' + target);
}

const config = $('⚙️ Workflow Config (修改网站入口)').first().json;
const targetHostname = config.targetHostname;
const robotsNodeData = $('Parse robots.txt Rules').first()?.json || {};
const robotsRules = robotsNodeData.rules || robotsNodeData.disallowRegexes || [];
const userExcludePaths = config.excludePaths || [];
const recheckIntervalHours = config.recheckIntervalHours || 168; // 默认7天

let crawlIndex = {};
try {
  const rawIndex = $('Fetch Crawl Index').first()?.json;
  if (rawIndex && typeof rawIndex === 'object' && !rawIndex.error && !rawIndex.statusCode) {
    for (const [k, v] of Object.entries(rawIndex)) {
      crawlIndex[k.replace(/\/+$/, '')] = v;
    }
  }
} catch (e) {
  crawlIndex = {};
}

const incomingItems = $input.all();
const validUrls = [];
const seenUrlsInBatch = new Set();
const redirectsFiltered = [];
const blockedByRobots = [];
const blockedStatic = [];
const unchangedSkipped = [];
const discoveredUrlSet = new Set();


for (const item of incomingItems) {
  const rawUrl = (item.json.url || '').trim().replace(/\/+$/, '');
  const lastmod = item.json.lastmod || null;
  if (!rawUrl) continue;

  try {
    const match = rawUrl.match(/^https?:\/\/([^\/\?]+)(\/[^\?]*)?(\?.*)?$/i);
    if (!match) continue;

    const hostname = (match[1] || '').toLowerCase().replace(/:(80|443)$/, '');
    const pathname = match[2] || '/';
    const search = match[3] || '';

    // 1. 严格域名限制 (Strict Domain Boundary)
    if (!isAllowedHost(hostname, targetHostname)) continue;

    // 2. 静态与系统资源过滤
    if (/\.(png|jpg|jpeg|gif|svg|webp|pdf|zip|mp4|css|js|woff|woff2|ico|xml|rss|atom|json|txt)$/i.test(pathname)) continue;
    if (/blog-feed|sitemap|robots\.txt/i.test(pathname)) continue;

    // 3. 用户自定义路径黑名单 (Config 动态输入，零硬编码)
    let isUserExcluded = false;
    for (const pattern of userExcludePaths) {
      if (!pattern) continue;
      if (pathname.includes(pattern) || new RegExp(pattern, 'i').test(pathname)) {
        redirectsFiltered.push({
          url: rawUrl,
          reason: `Matched user exclude pattern: "${pattern}"`
        });
        isUserExcluded = true;
        break;
      }
    }
    if (isUserExcluded) continue;

    // 4. 网关即时去重
    if (seenUrlsInBatch.has(rawUrl)) continue;
    seenUrlsInBatch.add(rawUrl);
    discoveredUrlSet.add(rawUrl);

    // 5. robots.txt RFC 9309 规范判定 (特异度最长规则优先，等长 Allow 优先)
    const pathAndQuery = pathname + search;
    let bestMatch = null;

    for (const rule of robotsRules) {
      const pattern = typeof rule === 'string' ? rule : rule.pattern;
      const type = typeof rule === 'string' ? 'disallow' : rule.type;
      const len = typeof rule === 'string' ? pattern.length : (rule.length || 0);

      try {
        if (new RegExp(pattern).test(pathAndQuery)) {
          if (!bestMatch || len > bestMatch.len) {
            bestMatch = { type, len, pattern };
          } else if (len === bestMatch.len && type === 'allow') {
            bestMatch = { type, len, pattern };
          }
        }
      } catch (e) {}
    }

    if (bestMatch && bestMatch.type === 'disallow') {
      blockedByRobots.push({ url: rawUrl, reason: `Disallowed by robots.txt rule: "${bestMatch.pattern}"` });
      continue;
    }

    // 6. 【三级增量决策体系 (Three-Tier Incremental Engine)】
    const indexedInfo = crawlIndex[rawUrl];
    let shouldCrawl = true;
    let skipReason = '';

    if (indexedInfo && indexedInfo.fileName && indexedInfo.hash) {
      if (lastmod && indexedInfo.lastmod) {
        if (lastmod <= indexedInfo.lastmod) {
          shouldCrawl = false;
          skipReason = `Sitemap lastmod unchanged (${lastmod} <= ${indexedInfo.lastmod})`;
        }
      } else {
        const lastCrawlMs = indexedInfo.lastCrawlTime ? new Date(indexedInfo.lastCrawlTime).getTime() : 0;
        const hoursPassed = (Date.now() - lastCrawlMs) / (1000 * 60 * 60);
        if (hoursPassed < recheckIntervalHours) {
          shouldCrawl = false;
          skipReason = `No lastmod provided; crawled ${Math.round(hoursPassed)}h ago (within ${recheckIntervalHours}h verification TTL)`;
        } else {
          shouldCrawl = true;
        }
      }
    }

    if (!shouldCrawl) {
      unchangedSkipped.push({
        url: rawUrl,
        lastmod: lastmod,
        indexedLastmod: indexedInfo?.lastmod,
        reason: skipReason
      });
      continue;
    }

    validUrls.push({
      url: rawUrl,
      lastmod: lastmod,
      hostname: hostname,
      pathname: pathname,
      isRecheck: !!(indexedInfo && indexedInfo.hash)
    });
  } catch (err) {}
}

// 7. 【线上删除页面探查 (Stale Webpage Detection)】
const staleUrls = [];
for (const [indexedUrl, info] of Object.entries(crawlIndex)) {
  if (info && info.status !== 'deleted' && !discoveredUrlSet.has(indexedUrl)) {
    staleUrls.push({
      url: indexedUrl,
      fileName: info.fileName,
      reason: 'Page no longer discovered in sitemap or homepage links'
    });
  }
}

return [{
  json: {
    hasUrls: validUrls.length > 0,
    urlsToCrawlCount: validUrls.length,
    validUrls: validUrls,
    staleUrlsCount: staleUrls.length,
    staleUrls: staleUrls,
    diagnostics: { ...incomingItems[0]?.json.discovery, redirectsFiltered, unchangedSkipped,
      staleUrls, blockedByRobots, blockedStatic }
  }
}];

