// 纯 JS 确定性 Hash 函数
function generateContentHash(str) {
  let h1 = 0xdeadbeef, h2 = 0x41c6ce57;
  for (let i = 0; i < str.length; i++) {
    const ch = str.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507);
  h1 ^= Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507);
  h2 ^= Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(16).padStart(12, '0');
}

// 【URL is Identity: 基于标准 URL 对象生成永久稳定的文件名】
function generateStableFileName(siteName, rawUrl) {
  let pathname = '';
  let search = '';
  try {
    const u = new URL(rawUrl);
    pathname = u.pathname || '';
    search = u.search || '';
  } catch (e) {
    try {
      const parts = rawUrl.replace(/^https?:\/\/[^\/]+/, '').split('?');
      pathname = parts[0] || '';
      search = parts[1] ? ('?' + parts[1]) : '';
    } catch (e2) {
      pathname = '';
    }
  }

  let slug = pathname.replace(/^\/+|\/+$/g, '').replace(/[^a-zA-Z0-9_-]/g, '-').trim();
  if (!slug) slug = 'index';
  if (search) {
    const q = search.replace(/[^a-zA-Z0-9_-]/g, '-').substring(0, 30);
    slug = slug + q;
  }
  if (slug.length > 80) slug = slug.substring(0, 80);
  return `raw/${siteName}/${slug}.md`;
}

// 【通用动态内容降噪与去重算法 (Dynamic & Content-Agnostic Cleaner)】
// 彻底剔除任何特定网站的硬编码文本匹配，完全基于标准语义标签、链接密度与信息论启发式算法
function cleanMarkdownDynamically(md) {
  if (!md || typeof md !== 'string') return '';

  // 1. 动态剥离页内锚点跳转链接 (负向后行断言 (?<!\!) 确保绝不破坏图片 ![] 语法)
  md = md.replace(/(?<!\!)\[[^\]]*\]\([^)]*#[^)]*\)/gi, '');

  // 2. 动态剥离空文本链接 (负向后行断言 (?<!\!) 确保无 alt 的 Markdown 图片 ![](url) 完好保留)
  md = md.replace(/(?<!\!)\[\s*\]\([^)]*\)/gi, '');

  // 3. 动态链接密度剪枝算法 (Link Density Filter - 浏览器阅读模式核心算法)
  // 核心原理：正文的链接密度通常 < 0.25；而分类目录、导航菜单、标签云的链接密度 > 0.65
  const lines = md.split('\n');
  const cleanedLines = [];
  let i = 0;

  while (i < lines.length) {
    const line = lines[i];
    // 探测 Markdown 列表项起始 (*, -, +)
    if (/^\s*[\*\-\+]\s+/.test(line)) {
      const listBlock = [];
      while (i < lines.length && (/^\s*[\*\-\+]\s+/.test(lines[i]) || (lines[i].trim() && lines[i].startsWith('  ')))) {
        listBlock.push(lines[i]);
        i++;
      }
      // 计算当前列表块的 Link Density
      const blockText = listBlock.join(' ');
      const totalLen = blockText.trim().length;
      const links = blockText.match(/\[([^\]]*)\]\([^)]*\)/g) || [];

      let linkTextLen = 0;
      for (const link of links) {
        const m = link.match(/\[([^\]]*)\]/);
        if (m && m[1]) linkTextLen += m[1].length;
      }

      const linkDensity = totalLen > 0 ? (linkTextLen / totalLen) : 0;

      // 如果列表包含 3 个以上链接且链接字符占比超过 65%，判定为高密度导航/目录块，动态剔除
      if (links.length >= 3 && linkDensity > 0.65) {
        continue;
      } else {
        cleanedLines.push(...listBlock);
        continue;
      }
    } else {
      cleanedLines.push(line);
      i++;
    }
  }

  // 4. 连续重复行动态去重 (Consecutive Duplicate Line De-duplication)
  // 消除轮播图、跑马灯、响应式重复渲染导致的同构行
  const dedupedLines = [];
  for (const line of cleanedLines) {
    const trimmed = line.trim();
    if (trimmed && dedupedLines.length > 0 && dedupedLines[dedupedLines.length - 1].trim() === trimmed) {
      continue;
    }
    dedupedLines.push(line);
  }

  // 5. 空行动态规整 (最多保留两个换行)
  return dedupedLines.join('\n').replace(/\n{3,}/g, '\n\n').trim();
}

const config = $('⚙️ Workflow Config (修改网站入口)').first().json;
const siteName = config.siteName || 'custom_site';
const targetHostname = config.targetHostname;


const enrichedItems = [];

for (const item of $input.all()) {
  const data = item.json;
  const resultObj = (data.results && Array.isArray(data.results) && data.results[0]) ? data.results[0] : data;
  const url = resultObj.url || data.url || item.json.url || '';
  let lastmod = item.json.lastmod || null;

  // 1. 拦截 HTTP 400+/500 异常页面，绝不把死链存入 Obsidian
  if ((resultObj.status_code && resultObj.status_code >= 400) || resultObj.success === false) {
    enrichedItems.push({ json: { failedCrawl: {
      failedUrl: url,
      errorMessage: resultObj.error_message || 'Crawl failed',
      failedAt: new Date().toISOString()
    } } });
    continue;
  }

  // 2. 自动从响应头补全 Last-Modified
  if (!lastmod) {
    const respHeaders = resultObj.response_headers || {};
    const srvMod = respHeaders['last-modified'] || respHeaders['Last-Modified'];
    if (srvMod) {
      try {
        lastmod = new Date(srvMod).toISOString().split('T')[0];
      } catch (e) {
        lastmod = srvMod;
      }
    }
  }

  // 3. 正文 Markdown 提取与纯动态清洗去噪（优先采用未过滤图片与嵌入媒体的 raw_markdown）
  let rawMarkdown = '';
  if (resultObj.markdown) {
    if (typeof resultObj.markdown === 'string') {
      rawMarkdown = resultObj.markdown;
    } else if (typeof resultObj.markdown === 'object') {
      rawMarkdown = resultObj.markdown.raw_markdown || resultObj.markdown.fit_markdown || '';
    }
  }
  if (!rawMarkdown) {
    rawMarkdown = resultObj.cleaned_html || resultObj.content || '';
  }

  // 执行纯动态清洗（无任何硬编码字符串）
  const cleanedMarkdown = cleanMarkdownDynamically(rawMarkdown);

  // 4. 【Title is Metadata】真实标题保存在 Frontmatter 中
  let title = (resultObj.metadata?.title || data.metadata?.title || resultObj.title || data.title || 'Untitled Page')
    .replace(/[\r\n]/g, ' ')
    .replace(/"/g, '\\"')
    .trim();
  if (title.length > 120) title = title.substring(0, 120);

  // 提取 Crawl4AI 探测到的 YouTube 视频或媒体并保证其在正文中呈现
  const mediaVideos = resultObj.media?.videos || [];
  const youtubeUrls = [];
  for (const v of mediaVideos) {
    const vUrl = typeof v === 'string' ? v : (v?.src || v?.url || '');
    if (vUrl && /youtube\.com|youtu\.be/i.test(vUrl)) {
      if (!youtubeUrls.includes(vUrl)) youtubeUrls.push(vUrl);
    }
  }
  if (Array.isArray(resultObj.links?.external)) {
    for (const l of resultObj.links.external) {
      const lHref = l?.href || l?.url || '';
      if (lHref && /youtube\.com|youtu\.be/i.test(lHref)) {
        if (!youtubeUrls.includes(lHref)) youtubeUrls.push(lHref);
      }
    }
  }

  let extraMediaSection = '';
  if (youtubeUrls.length > 0) {
    const missingVideos = youtubeUrls.filter(u => !cleanedMarkdown.includes(u));
    if (missingVideos.length > 0) {
      extraMediaSection = '\n\n### 关联视频资源 (Videos)\n' + missingVideos.map(u => `- [YouTube 视频](${u})`).join('\n');
    }
  }

  const finalMarkdownContent = `${cleanedMarkdown}${extraMediaSection}`;
  const hash = generateContentHash(finalMarkdownContent);
  const crawlTime = new Date().toISOString();
  const fileName = generateStableFileName(siteName, url);

  const enrichedMarkdown = `---` + `\n` +
`title: "${title}"` + `\n` +
`url: "${url}"` + `\n` +
`crawl_time: "${crawlTime}"` + `\n` +
`hash: "${hash}"` + `\n` +
`---` + `\n\n` +
`# ${title}` + `\n\n` +
`${finalMarkdownContent}`;

  enrichedItems.push({
    json: {
      url,
      title,
      siteName,
      hash,
      lastmod,
      fileName,
      content: enrichedMarkdown
    }
  });
}

return enrichedItems;

const config = $('⚙️ Workflow Config (修改网站入口)').first().json;
const siteName = config.siteName || 'custom_site';
const autoDeleteStale = config.autoDeleteStale !== false;

let crawlIndex = {};
try {
  const rawIndex = $('Fetch Crawl Index').first()?.json;
  if (rawIndex && typeof rawIndex === 'object' && !rawIndex.error && !rawIndex.statusCode) {
    for (const [k, v] of Object.entries(rawIndex)) {
      crawlIndex[k.replace(/\/+$/, '')] = v;
    }
  }
} catch (e) {
  crawlIndex = {};
}

// 仅获取【写入 Obsidian 成功】的条目实施事务提交 (Two-Phase Consistency)
let storedItems = [];
try {
  storedItems = $('Store Crawled Markdown').all();
} catch (e) {
  storedItems = [];
}

function outputItems(name) {
  const result = [];
  for (let run = 0; ; run++) {
    let items;
    try { items = $(name).all(0, run); } catch { break; }
    if (!items.length) break;
    result.push(...items);
  }
  return result;
}
const extracted = outputItems('Metadata & Taxonomy Enrichment');
const enrichedItems = extracted.filter(item => item.json.fileName);

const currentRun = $('Robots.txt & Gateway Filter').first().json.diagnostics || {};
const duplicateLinks = currentRun.duplicateLinks || [];
const redirectsFiltered = currentRun.redirectsFiltered || [];
const unchangedSkipped = currentRun.unchangedSkipped || [];
const failedCrawls = [...extracted, ...outputItems('Record Crawl Error')]
  .map(item => item.json.failedCrawl).filter(Boolean);
const detectedStaleUrls = currentRun.staleUrls || [];

let crawledCount = enrichedItems.length;
let changedCount = 0;
let unchangedAfterCrawlCount = 0;
const crawledThisRun = [];

// 建立 enriched map 供提取 metadata
const enrichedMap = new Map();
for (const item of enrichedItems) {
  if (item.json.url) {
    enrichedMap.set(item.json.url.replace(/\/+$/, ''), item.json);
  }
}

// 遍历真正成功持久化的条目更新 Index
for (const item of storedItems) {
  const pairedIndex = item.pairedItem?.item;
  let sourceItem = null;
  if (typeof pairedIndex === 'number') {
    try {
      sourceItem = $('Metadata & Taxonomy Enrichment').item(pairedIndex)?.json;
    } catch (e) {}
  }
  if (!sourceItem) {
    sourceItem = Array.from(enrichedMap.values())[0];
  }
  if (!sourceItem || !sourceItem.url) continue;

  const cleanUrl = sourceItem.url.replace(/\/+$/, '');
  const oldHash = crawlIndex[cleanUrl]?.hash;
  const newHash = sourceItem.hash;

  if (oldHash && oldHash === newHash) {
    unchangedAfterCrawlCount++;
  } else {
    changedCount++;
  }

  crawlIndex[cleanUrl] = {
    fileName: sourceItem.fileName,
    hash: newHash,
    lastmod: sourceItem.lastmod || (crawlIndex[cleanUrl]?.lastmod) || null,
    lastCrawlTime: new Date().toISOString(),
    status: 'success'
  };

  crawledThisRun.push({
    url: cleanUrl,
    fileName: sourceItem.fileName,
    title: sourceItem.title,
    hashChanged: oldHash !== newHash,
    status: 'success'
  });
}

// 处理线上已删除的孤儿页面 (Stale Cleanup)
const staleFilesToDelete = [];
for (const stale of detectedStaleUrls) {
  const cleanUrl = stale.url.replace(/\/+$/, '');
  if (autoDeleteStale) {
    if (stale.fileName) {
      staleFilesToDelete.push({ fileName: stale.fileName, url: cleanUrl });
    }
    delete crawlIndex[cleanUrl]; // 从索引中注销
  } else {
    if (crawlIndex[cleanUrl]) {
      crawlIndex[cleanUrl].status = 'stale_online';
    }
  }
}

const failedReport = [];
for (const f of failedCrawls) {
  const cleanUrl = f.failedUrl.replace(/\/+$/, '');
  failedReport.push({
    url: cleanUrl,
    error: f.errorMessage,
    failedAt: f.failedAt
  });
  if (crawlIndex[cleanUrl]) {
    crawlIndex[cleanUrl].status = 'failed';
    crawlIndex[cleanUrl].lastError = f.errorMessage;
  }
}

// 【工业级全景审计报告 (Production Audit Report)】
const report = {
  crawlTime: new Date().toISOString(),
  siteName: siteName,
  targetUrl: config.targetUrl,
  status: failedReport.length > 0 ? 'completed_with_errors' : ((changedCount > 0 || staleFilesToDelete.length > 0) ? 'updated_with_changes' : 'all_up_to_date'),
  summary: {
    totalRawDiscovered: currentRun.rawDiscoveredCount || 0,
    sitemapDiscovered: currentRun.sitemapCount || 0,
    homepageProbeDiscovered: currentRun.probeCount || 0,
    uniquePagesDiscovered: currentRun.uniquePagesCount || 0,
    blockedByRobotsCount: (currentRun.blockedByRobots || []).length,
    blockedStaticCount: (currentRun.blockedStatic || []).length,
    duplicateLinksMergedCount: duplicateLinks.length,
    redirectsFilteredCount: redirectsFiltered.length,
    unchangedSkippedCount: unchangedSkipped.length,
    crawledThisRunCount: crawledCount,
    changedCount: changedCount,
    unchangedAfterCrawlCount: unchangedAfterCrawlCount,
    staleDeletedCount: staleFilesToDelete.length,
    failedCount: failedReport.length,
    totalIndexedInVault: Object.keys(crawlIndex).length
  },
  crawledThisRun: crawledThisRun,
  staleUrlsDeleted: staleFilesToDelete,
  duplicateLinksMerged: duplicateLinks,
  redirectsFiltered: redirectsFiltered,
  unchangedSkipped: unchangedSkipped,
  failedUrls: failedReport
};

return [{
  json: {
    siteName: siteName,
    hasChanges: changedCount > 0 || staleFilesToDelete.length > 0 || failedReport.length > 0,
    indexContent: JSON.stringify(crawlIndex, null, 2),
    reportContent: JSON.stringify(report, null, 2),
    staleCount: staleFilesToDelete.length,
    staleFilesToDelete: staleFilesToDelete
  }
}];

const errorItems = $input.all();
for (const item of errorItems) {
  const errorData = item.json;
  const pairedIndex = item.pairedItem?.item;

  let failedUrl = '';
  try {
    failedUrl = $('Unpack URLs').item(pairedIndex || 0)?.json?.url;
  } catch (e) {
    failedUrl = errorData?.url || errorData?.item?.url || 'unknown_url';
  }

  const errorMessage = errorData.error?.message || errorData.message || 'Crawl request failed';

  item.json.failedCrawl = {
    failedUrl: failedUrl,
    errorMessage: errorMessage,
    failedAt: new Date().toISOString()
  };
}

return errorItems;
